170	    public String getEmail() {
171	        return this.email;
172	    }
173	
174	    public void setEmail(String email) {
175	        this.email = email;
176	    }
177	
178	    public String getPostcode() {
179	        return this.postcode;
180	    }
181	
182	    public void setPostcode(String postcode) {
183	        this.postcode = postcode;
184	    }
185	
186	    public LocalDate getRegistrationDate() {
187	        return this.registrationDate;
188	    }
189	
190	    public void setRegistrationDate(LocalDate registrationDate) {
191	        this.registrationDate = registrationDate;
192	    }
193	
194	    public LocalDate getBirthDate() {
195	        return this.birthDate;
196	    }
197	
198	    public void setBirthDate(LocalDate birthDate) {
199	        this.birthDate = birthDate;
200	    }
201	
202	    public String getMemberId() {
203	        return this.memberId;
204	    }
205	
206	    public void setMemberId(String memberId) {
207	        this.memberId = memberId;
208	    }
209	
210	    /**
211	     * The owner's current primary identifier: the single external identifier by which this owner is
212	     * known, namely the {@link #getMemberId() member id}. Every consumer that records the primary
213	     * identifier reads it through this method, so a future change of primary identifier follows
214	     * automatically.
215	     */
216	    public String getPrimaryIdentifier() {
217	        return getMemberId();
218	    }
219	
220	    public String getHouseholdId() {
221	        return this.householdId;
222	    }
223	
224	    public void setHouseholdId(String householdId) {
225	        this.householdId = householdId;
226	    }
227	
228	    public Integer getNamesakeCount() {
229	        return this.namesakeCount;
230	    }
231	
232	    public void setNamesakeCount(Integer namesakeCount) {
233	        this.namesakeCount = namesakeCount;
234	    }
235	
236	    public Integer getHouseholdSize() {
237	        return this.householdSize;
238	    }
239	
240	    public void setHouseholdSize(Integer householdSize) {
241	        this.householdSize = householdSize;
242	    }
243	
244	    /**
245	     * The ceiling applied to this owner's {@link #getMembershipLevel() membership level}: one above
246	     * the highest membership level held by the owner's household members when this owner was created.
247	     * {@code null} when the owner had no existing household member and so is uncapped.
248	     */
249	    public Integer getMembershipLevelCap() {
250	        return this.membershipLevelCap;
251	    }
252	
253	    public void setMembershipLevelCap(Integer membershipLevelCap) {
254	        this.membershipLevelCap = membershipLevelCap;
255	    }
256	
257	    /**
258	     * Whether this owner, though not a hard duplicate, matches an existing owner's last name by
259	     * Soundex and shares its postcode while holding a different identity key. Resolved at creation
260	     * and stored so it is reported consistently on every later read.
261	     */
262	    public Boolean getPossibleDuplicate() {
263	        return this.possibleDuplicate;
264	    }
265	
266	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
267	        this.possibleDuplicate = possibleDuplicate;
268	    }
269	
270	    /**
271	     * The id of the existing owner this owner is a possible duplicate of, or {@code null} when it
272	     * is not a possible duplicate.
273	     */
274	    public Integer getPossibleDuplicateOf() {
275	        return this.possibleDuplicateOf;
276	    }
277	
278	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
279	        this.possibleDuplicateOf = possibleDuplicateOf;
280	    }
281	
282	    /**
283	     * Whether this owner has been soft-deleted. A soft-deleted owner keeps its row and remains
284	     * retrievable, but is ignored by the create endpoint's duplicate and identity checks. A newly
285	     * created owner is never deleted.
286	     */
287	    public boolean isDeleted() {
288	        return this.deleted;
289	    }
290	
291	    public void setDeleted(boolean deleted) {
292	        this.deleted = deleted;
293	    }
294	
295	    /**
296	     * The owner's identity key: the single derived value used to detect duplicate owners, formed as
297	     * the SHA-256 hex digest of {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}
298	     * where an absent telephone or email contributes an empty string. Because the telephone is part
299	     * of the key, housemates that share a last name and postcode but hold different telephones have
300	     * distinct identity keys and are both allowed (and merely flagged as possible duplicates).
301	     */
302	    public String getIdentityKey() {
303	        String key = orEmpty(this.telephone) + "|" + orEmpty(this.email) + "|" + Soundex.of(this.getLastName());
304	        return Sha256.hex(key);
305	    }
306	
307	    private static String orEmpty(String value) {
308	        return value == null ? "" : value;
309	    }
310	
311	    /**
312	     * The owner's fiscal year, formatted {@code 'FY<YY>'}: the two-digit FY segment carried by the
313	     * {@link #getMemberId() member id} (the fiscal year, starting 1 July, of the business-day-adjusted
314	     * registration date when the identity was assigned; see {@link FiscalYear}). Absent until a member
315	     * id has been assigned.
316	     */
317	    public String getFiscalYear() {
318	        if (this.memberId == null) {
319	            return null;
320	        }
321	        int fiscalYearStart = regionLength();
322	        return "FY" + this.memberId.substring(fiscalYearStart, fiscalYearStart + 2);
323	    }
324	
325	    /**
326	     * The owner's tenure in whole elapsed fiscal years: the number of 1 July boundaries crossed
327	     * from the {@link #getRegistrationDate() registration date} up to today (see {@link FiscalYear}).
328	     * An owner still in their registration fiscal year has a tenure of zero. Absent until a
329	     * registration date is present.
330	     */
331	    public Long getTenureFiscalYears() {
332	        if (this.registrationDate == null) {
333	            return null;
334	        }
335	        return FiscalYear.elapsed(this.registrationDate, LocalDate.now());
336	    }
337	
338	    /**
339	     * The owner's membership points, a score derived from the owner's own fields: starting from 0,
340	     * the owner earns 2 points when an email address is present, 1 point when this owner has no
341	     * namesakes ({@code namesakeCount} is 0), 2 points for a household of 3 or more members, and 3
342	     * points once the owner's {@link #getTenureFiscalYears() tenure} spans at least one full fiscal
343	     * year (the registration and current dates fall in different fiscal years).
344	     */
345	    public Integer getMembershipPoints() {
346	        int points = 0;
347	        boolean hasEmail = this.email != null && !this.email.isEmpty();
348	        if (hasEmail) {
349	            points += 2;
350	        }
351	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
352	        if (unique) {
353	            points += 1;
354	        }
355	        boolean sharedHousehold = this.householdSize != null && this.householdSize >= 3;
356	        if (sharedHousehold) {
357	            points += 2;
358	        }
359	        Long tenureFiscalYears = getTenureFiscalYears();
360	        boolean tenured = tenureFiscalYears != null && tenureFiscalYears >= 1;
361	        if (tenured) {
362	            points += 3;
363	        }
364	        return points;
365	    }
366	
367	    /**
368	     * The owner's membership level, a number from 1 to 4 derived from the owner's
369	     * {@link #getMembershipPoints() membership points}: 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and
370	     * 4 for 6 or more. The level is then held to its {@link #getMembershipLevelCap() cap} (one above
371	     * the highest level among the owner's household members at creation), so a new owner cannot rank
372	     * more than one level above their household. An uncapped owner keeps the derived level.
373	     */
374	    public Integer getMembershipLevel() {
375	        int level = derivedMembershipLevel();
376	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
377	            return this.membershipLevelCap;
378	        }
379	        return level;
380	    }
381	
382	    private int derivedMembershipLevel() {
383	        int points = getMembershipPoints();
384	        if (points >= 6) {
385	            return 4;
386	        }
387	        if (points >= 4) {
388	            return 3;
389	        }
390	        if (points >= 2) {
391	            return 2;
392	        }
393	        return 1;
394	    }
395	
396	    /**
397	     * The owner's locality: the REGION segment of the {@link #getMemberId() member id} (the region
398	     * derived from the postcode when the identity was assigned), or {@link Regions#UNKNOWN} before a
399	     * member id has been assigned.
400	     */
401	    public String getLocality() {
402	        if (this.memberId == null) {
403	            return Regions.UNKNOWN;
404	        }
405	        return this.memberId.substring(0, regionLength());
406	    }
407	
408	    /**
409	     * The length of the leading REGION segment of the {@link #getMemberId() member id}: its run of
410	     * leading letters, ending where the two-digit fiscal-year segment begins.
411	     */
412	    private int regionLength() {
413	        int i = 0;
414	        while (i < this.memberId.length() && Character.isLetter(this.memberId.charAt(i))) {
415	            i++;
416	        }
417	        return i;
418	    }
419	
420	    /**
421	     * The owner's timezone: the IANA timezone name for the owner's {@link #getLocality() locality}
422	     * from the fixed region-to-timezone table (NSW&rarr;Australia/Sydney, VIC&rarr;Australia/Melbourne,
423	     * QLD&rarr;Australia/Brisbane), or absent when the locality has no known timezone.
424	     */
425	    public String getTimezone() {
426	        return Regions.timezoneOf(getLocality());
427	    }
428	
429	    /**
430	     * The owner's segment, formatted {@code '<TIER>_<AREA>'}. TIER is {@code "PREMIUM"} when the
431	     * owner's {@link #getMembershipLevel() membership level} is 3 or more, otherwise
432	     * {@code "STANDARD"}. AREA is {@code "METRO"} when the owner's {@link #getLocality() locality} is
433	     * a known region (NSW, VIC or QLD), otherwise {@code "REGIONAL"}.
434	     */
435	    public String getOwnerSegment() {
436	        String tier = getMembershipLevel() >= 3 ? "PREMIUM" : "STANDARD";
437	        String area = Regions.isKnown(getLocality()) ? "METRO" : "REGIONAL";
438	        return tier + "_" + area;
439	    }
440	
441	    /**
442	     * The owner's preferred contact channel, derived from the owner's own fields:
443	     * {@code "EMAIL"} when an {@link #getEmail() email} is present, otherwise {@code "PHONE"}.
444	     */
445	    public String getContactPreference() {
446	        boolean hasEmail = this.email != null && !this.email.isEmpty();
447	        return hasEmail ? "EMAIL" : "PHONE";
448	    }
449	
450	    /**
451	     * The owner's age band, derived from the owner's own fields: the whole years between
452	     * {@link #getBirthDate() birth date} and {@link #getRegistrationDate() registration date}
453	     * classified as {@code "MINOR"} (under 18), {@code "ADULT"} (18-64) or {@code "SENIOR"}
454	     * (65 or older). Absent until a birth date and a registration date are both present.
455	     */
456	    public String getAgeBand() {
457	        if (this.birthDate == null || this.registrationDate == null) {
458	            return null;
459	        }
460	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
461	        if (age < 18) {
462	            return "MINOR";
463	        }
464	        return age < 65 ? "ADULT" : "SENIOR";
465	    }
466	
467	    /**
468	     * The registration date this owner will be persisted with: the supplied
469	     * {@link #getRegistrationDate() registration date} rolled forward to a business day, or today's
470	     * business-day-adjusted date when none was supplied. Every value derived from the registration
471	     * date (such as the FY segment of the {@link #getMemberId() member id}) uses this date, so a
472	     * caller assigning the identity before persistence obtains the same value that
473	     * {@link #resolveRegistrationDate() persistence} later stores.
474	     */
475	    public LocalDate effectiveRegistrationDate() {
476	        LocalDate date = this.registrationDate != null ? this.registrationDate : LocalDate.now();
477	        return BusinessDay.onOrAfter(date);
478	    }
479	
480	    /**
481	     * Resolve the effective registration date before persisting so a newly registered owner always
482	     * has a business-day registration date, defaulted to today when none was supplied. Idempotent:
483	     * a date already resolved via {@link #effectiveRegistrationDate()} is left unchanged.
484	     */
485	    @PrePersist
486	    private void resolveRegistrationDate() {
487	        this.registrationDate = effectiveRegistrationDate();
488	    }
489	
490	    /**
491	     * The owner's self link: the canonical API path of this owner, formatted
492	     * {@code "/api/owners/<id>"}. Absent until the owner has been assigned an id.
493	     */
494	    public String getSelfLink() {
495	        if (this.getId() == null) {
496	            return null;
497	        }
498	        return "/api/owners/" + this.getId();
499	    }
500	
501	    protected Set<Pet> getPetsInternal() {
502	        if (this.pets == null) {
503	            this.pets = new HashSet<>();
504	        }
505	        return this.pets;
506	    }
507	
508	    protected void setPetsInternal(Set<Pet> pets) {
509	        this.pets = pets;
510	    }
511	
512	    public List<Pet> getPets() {
513	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
514	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
515	        return Collections.unmodifiableList(sortedPets);
516	    }
517	
518	    public void setPets(List<Pet> pets) {
519	        this.pets = new HashSet<>(pets);
520	    }
521	
522	    public void addPet(Pet pet) {
523	        getPetsInternal().add(pet);
524	        pet.setOwner(this);
525	    }
526	
527	    /**
528	     * Return the Pet with the given name, or null if none found for this Owner.
529	     *
530	     * @param name to test
531	     * @return true if pet name is already in use
532	     */
533	    public Pet getPet(String name) {
534	        return getPet(name, false);
535	    }
536	
537	    /**
538	     * Return the Pet with the given name, or null if none found for this Owner.
539	     *
540	     * @param name to test
541	     * @return true if pet name is already in use
542	     */
543	    public Pet getPet(String name, boolean ignoreNew) {
544	        name = name.toLowerCase();
545	        for (Pet pet : getPetsInternal()) {
546	            if (!ignoreNew || !pet.isNew()) {
547	                String compName = pet.getName();
548	                compName = compName.toLowerCase();
549	                if (compName.equals(name)) {
550	                    return pet;
551	                }
552	            }
553	        }
554	        return null;
555	    }
556	
557	    public Pet getPet(Integer petId) {
558	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
559	    }
560	
561	    @Override
562	    public String toString() {
563	        return new ToStringCreator(this)
564	
565	            .append("id", this.getId())
566	            .append("new", this.isNew())
567	            .append("lastName", this.getLastName())
568	            .append("firstName", this.getFirstName())
569	            .append("address", this.address)
570	            .append("city", this.city)
571	            .append("telephone", this.telephone)
572	            .append("email", this.email)
573	            .toString();
574	    }
575	}
