244	        this.addressFormNormalizer.normalize(ownerFieldsDto);
245	        this.ownerRequestValidator.validate(ownerFieldsDto);
246	        this.postcodeValidator.validate(ownerFieldsDto);
247	        this.cityOwnerLimitValidator.validate(ownerFieldsDto);
