251	        ownerFieldsDto.setEmail(this.emailNormalizer.normalize(ownerFieldsDto.getEmail()));
252	        this.disposableEmailDomainValidator.validate(ownerFieldsDto.getEmail());
253	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
254	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
255	        // The householdId is deterministic from (lastName, postcode), so every owner carries the
256	        // identifier of its household automatically.
257	        owner.setHouseholdId(
258	            this.householdIdGenerator.generate(owner.getLastName(), owner.getPostcode()));
259	        if (sharesHousehold) {
260	            // A declared household member is deliberately allowed and, being declared, is never a
261	            // suspected duplicate.
262	            owner.setPossibleDuplicate(false);
263	            owner.setPossibleDuplicateOf(null);
264	        } else {
265	            this.duplicateOwnerValidator.validate(owner);
266	            Integer possibleDuplicateOf = this.possibleDuplicateDetector.findPossibleDuplicate(owner);
267	            owner.setPossibleDuplicate(possibleDuplicateOf != null);
