26	public final class FiscalYear {
27	
28	    /** The month on whose first day each fiscal year starts. */
29	    private static final Month START = Month.JULY;
30	
31	    private FiscalYear() {
32	    }
33	
34	    /**
35	     * The calendar year in which the fiscal year containing the given date ends. Dates on or after
36	     * 1 July belong to the fiscal year ending the following calendar year; earlier dates belong to
37	     * the one ending in their own calendar year.
38	     */
39	    public static int endingYear(LocalDate date) {
40	        return date.getMonthValue() >= START.getValue() ? date.getYear() + 1 : date.getYear();
41	    }
42	
43	    /**
44	     * The two-digit fiscal-year segment of the given date: the last two digits of its
45	     * {@link #endingYear(LocalDate) ending year}, zero-padded (e.g. {@code '27'}).
46	     */
47	    public static String twoDigit(LocalDate date) {
48	        return String.format("%02d", endingYear(date) % 100);
49	    }
50	
51	    /**
52	     * The fiscal year of the given date formatted {@code 'FY<YY>'}, where YY is its
53	     * {@link #twoDigit(LocalDate) two-digit segment} (e.g. {@code 'FY27'}).
54	     */
55	    public static String label(LocalDate date) {
56	        return "FY" + twoDigit(date);
57	    }
58	
59	    /**
60	     * The number of whole fiscal years elapsed from {@code from} to {@code to}: the count of 1 July
61	     * boundaries crossed between the two dates. Two dates in the same fiscal year give 0.
62	     */
63	    public static long elapsed(LocalDate from, LocalDate to) {
64	        return endingYear(to) - endingYear(from);
65	    }

