     * The raw {@link #getTelephone() telephone} stays in E.164 form. Absent until a telephone has
     * been set.
     */
    public String getTelephoneDisplay() {
        return Telephone.forDisplay(this.telephone);
    }

    public String getEmail() {
        return this.email;
    }

    public void setEmail(String email) {
        this.email = email;
    }

    public String getPostcode() {
        return this.postcode;
    }

    public void setPostcode(String postcode) {
        this.postcode = postcode;
    }

    public LocalDate getRegistrationDate() {
        return this.registrationDate;
    }

    public void setRegistrationDate(LocalDate registrationDate) {
        this.registrationDate = registrationDate;
    }

    public LocalDate getBirthDate() {
        return this.birthDate;
    }

    public void setBirthDate(LocalDate birthDate) {
        this.birthDate = birthDate;
    }

    public String getMemberId() {
        return this.memberId;
    }

    public void setMemberId(String memberId) {
        this.memberId = memberId;
    }

    /**
     * The owner's current primary identifier: the single external identifier by which this owner is
     * known, namely the {@link #getMemberId() member id}. Every consumer that records the primary
     * identifier reads it through this method, so a future change of primary identifier follows
     * automatically.
     */
    public String getPrimaryIdentifier() {
        return getMemberId();
    }

    public String getHouseholdId() {
        return this.householdId;
    }

    public void setHouseholdId(String householdId) {
        this.householdId = householdId;
    }

    public Integer getNamesakeCount() {
        return this.namesakeCount;
    }

    public void setNamesakeCount(Integer namesakeCount) {
        this.namesakeCount = namesakeCount;
    }

    public Integer getHouseholdSize() {
        return this.householdSize;
    }

    public void setHouseholdSize(Integer householdSize) {
        this.householdSize = householdSize;
    }

    /**
     * The ceiling applied to this owner's {@link #getMembershipLevel() membership level}: one above
     * the highest membership level held by the owner's household members when this owner was created.
     * {@code null} when the owner had no existing household member and so is uncapped.
     */
    public Integer getMembershipLevelCap() {
        return this.membershipLevelCap;
    }

    public void setMembershipLevelCap(Integer membershipLevelCap) {
        this.membershipLevelCap = membershipLevelCap;
    }

    /**
     * Whether this owner, though not a hard duplicate, matches an existing owner's last name by
     * Soundex and shares its postcode while holding a different identity key. Resolved at creation
     * and stored so it is reported consistently on every later read.
     */
    public Boolean getPossibleDuplicate() {
        return this.possibleDuplicate;
    }

    public void setPossibleDuplicate(Boolean possibleDuplicate) {
        this.possibleDuplicate = possibleDuplicate;
    }

    /**
     * The id of the existing owner this owner is a possible duplicate of, or {@code null} when it
     * is not a possible duplicate.
     */
    public Integer getPossibleDuplicateOf() {
        return this.possibleDuplicateOf;
    }

    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
        this.possibleDuplicateOf = possibleDuplicateOf;
    }

    /**
     * Whether this owner has been soft-deleted. A soft-deleted owner keeps its row and remains
     * retrievable, but is ignored by the create endpoint's duplicate and identity checks. A newly
     * created owner is never deleted.
     */
    public boolean isDeleted() {
        return this.deleted;
    }

    public void setDeleted(boolean deleted) {
        this.deleted = deleted;
    }

    /**
     * The owner's identity key: the single derived value used to detect duplicate owners, formed as
     * the SHA-256 hex digest of
     * {@code <versionTag> + '|' + normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}
     * where an absent telephone or email contributes an empty string. The leading
     * {@link IdentityVersion#TAG version tag} makes every version-2 key differ from the value the
     * same owner would have produced under version 1. Because the telephone is part of the key,
     * housemates that share a last name and postcode but hold different telephones have distinct
     * identity keys and are both allowed (and merely flagged as possible duplicates).
     */
    public String getIdentityKey() {
        String key = IdentityVersion.TAG + "|" + orEmpty(this.telephone) + "|" + orEmpty(this.email)
            + "|" + Soundex.of(this.getLastName());
        return Sha256.hex(key);
    }

    private static String orEmpty(String value) {
        return value == null ? "" : value;
    }

    /**
     * The owner's fiscal year, formatted {@code 'FY<YY>'}: the FY segment carried by the
     * {@link #getMemberId() member id} (the fiscal year, starting 1 July, of the business-day-adjusted
     * registration date when the identity was assigned; see {@link FiscalYear}). Absent until a member
     * id has been assigned.
     */
    public String getFiscalYear() {
        if (this.memberId == null) {
            return null;
        }
        return FiscalYear.label(effectiveRegistrationDate());
    }

    /**
     * The owner's tenure in whole elapsed fiscal years: the number of 1 July boundaries crossed
     * from the {@link #getRegistrationDate() registration date} up to today (see {@link FiscalYear}).
     * An owner still in their registration fiscal year has a tenure of zero. Absent until a
     * registration date is present.
     */
    public Long getTenureFiscalYears() {
        if (this.registrationDate == null) {
            return null;
        }
        return FiscalYear.elapsed(this.registrationDate, LocalDate.now());
    }

    /**
     * The owner's membership points, a score derived from the owner's own fields: starting from 0,
     * the owner earns 2 points when an email address is present, 1 point when this owner has no
     * namesakes ({@code namesakeCount} is 0), 2 points for a household of 3 or more members, and 3
     * points once the owner's {@link #getTenureFiscalYears() tenure} spans at least one full fiscal
     * year (the registration and current dates fall in different fiscal years).
     */
    public Integer getMembershipPoints() {
        int points = 0;
        boolean hasEmail = this.email != null && !this.email.isEmpty();
        if (hasEmail) {
            points += 2;
        }
        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
        if (unique) {
            points += 1;
        }
        boolean sharedHousehold = this.householdSize != null && this.householdSize >= 3;
        if (sharedHousehold) {
            points += 2;
        }
        Long tenureFiscalYears = getTenureFiscalYears();
        boolean tenured = tenureFiscalYears != null && tenureFiscalYears >= 1;
        if (tenured) {
            points += 3;
        }
        return points;
    }

    /**
     * The owner's membership level, a number from 1 to 4 derived from the owner's
     * {@link #getMembershipPoints() membership points}: 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and
     * 4 for 6 or more. The level is then held to its {@link #getMembershipLevelCap() cap} (one above
     * the highest level among the owner's household members at creation), so a new owner cannot rank
     * more than one level above their household. An uncapped owner keeps the derived level.
     */
    public Integer getMembershipLevel() {
        int level = derivedMembershipLevel();
        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
            return this.membershipLevelCap;
        }
        return level;
    }

    private int derivedMembershipLevel() {
        int points = getMembershipPoints();
        if (points >= 6) {
            return 4;
        }
        if (points >= 4) {
            return 3;
        }
        if (points >= 2) {
            return 2;
        }
        return 1;
    }

    /**
     * The owner's locality: the REGION segment of the {@link #getMemberId() member id} (the region
     * derived from the postcode when the identity was assigned), or {@link Regions#UNKNOWN} before a
     * member id has been assigned.
     */
    public String getLocality() {
        if (this.memberId == null) {
            return Regions.UNKNOWN;
        }
        return this.memberId.substring(0, regionLength());
    }

    /**
     * The length of the leading REGION segment of the {@link #getMemberId() member id}: its run of
     * leading letters, ending where the two-digit fiscal-year segment begins.
     */
    private int regionLength() {
        int i = 0;
        while (i < this.memberId.length() && Character.isLetter(this.memberId.charAt(i))) {
            i++;
        }
        return i;
    }

    /**
     * The owner's timezone: the IANA timezone name for the owner's {@link #getLocality() locality}
     * from the fixed region-to-timezone table (NSW&rarr;Australia/Sydney, VIC&rarr;Australia/Melbourne,
     * QLD&rarr;Australia/Brisbane), or absent when the locality has no known timezone.
     */
    public String getTimezone() {
        return Regions.timezoneOf(getLocality());
    }

    /**
     * The owner's segment, formatted {@code '<TIER>_<AREA>'}. TIER is {@code "PREMIUM"} when the
     * owner's {@link #getMembershipLevel() membership level} is 3 or more, otherwise
     * {@code "STANDARD"}. AREA is {@code "METRO"} when the owner's {@link #getLocality() locality} is
     * a known region (NSW, VIC or QLD), otherwise {@code "REGIONAL"}.
     */
    public String getOwnerSegment() {
        String tier = getMembershipLevel() >= 3 ? "PREMIUM" : "STANDARD";
        String area = Regions.isKnown(getLocality()) ? "METRO" : "REGIONAL";
        return tier + "_" + area;
    }

    /**
     * The owner's preferred contact channel, derived from the owner's own fields:
     * {@code "EMAIL"} when an {@link #getEmail() email} is present, otherwise {@code "PHONE"}.
     */
    public String getContactPreference() {
        boolean hasEmail = this.email != null && !this.email.isEmpty();
        return hasEmail ? "EMAIL" : "PHONE";
    }

    /**
     * The owner's age band, derived from the owner's own fields: the whole years between
     * {@link #getBirthDate() birth date} and {@link #getRegistrationDate() registration date}
     * classified as {@code "MINOR"} (under 18), {@code "ADULT"} (18-64) or {@code "SENIOR"}
     * (65 or older). Absent until a birth date and a registration date are both present.
     */
    public String getAgeBand() {
        if (this.birthDate == null || this.registrationDate == null) {
            return null;
        }
        int age = Period.between(this.birthDate, this.registrationDate).getYears();
        if (age < 18) {
            return "MINOR";
        }
        return age < 65 ? "ADULT" : "SENIOR";
    }

    /**
     * The registration date this owner will be persisted with: the supplied
     * {@link #getRegistrationDate() registration date} rolled forward to a business day, or today's
     * business-day-adjusted date when none was supplied. Every value derived from the registration
     * date (such as the FY segment of the {@link #getMemberId() member id}) uses this date, so a
     * caller assigning the identity before persistence obtains the same value that
     * {@link #resolveRegistrationDate() persistence} later stores.
     */
    public LocalDate effectiveRegistrationDate() {
        LocalDate date = this.registrationDate != null ? this.registrationDate : LocalDate.now();
        return BusinessDay.onOrAfter(date);
    }

    /**
     * Resolve the effective registration date before persisting so a newly registered owner always
     * has a business-day registration date, defaulted to today when none was supplied. Idempotent:
     * a date already resolved via {@link #effectiveRegistrationDate()} is left unchanged.
     */
    @PrePersist
    private void resolveRegistrationDate() {
        this.registrationDate = effectiveRegistrationDate();
    }

    /**
     * The owner's self link: the canonical API path of this owner, formatted
     * {@code "/api/owners/<id>"}. Absent until the owner has been assigned an id.
     */
    public String getSelfLink() {
        if (this.getId() == null) {
            return null;
        }
        return "/api/owners/" + this.getId();
    }

    protected Set<Pet> getPetsInternal() {
        if (this.pets == null) {
            this.pets = new HashSet<>();
        }
        return this.pets;
    }

    protected void setPetsInternal(Set<Pet> pets) {
        this.pets = pets;
    }

    public List<Pet> getPets() {
        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
        return Collections.unmodifiableList(sortedPets);
    }

    public void setPets(List<Pet> pets) {
        this.pets = new HashSet<>(pets);
    }

    public void addPet(Pet pet) {
        getPetsInternal().add(pet);
        pet.setOwner(this);
    }

    /**
     * Return the Pet with the given name, or null if none found for this Owner.
     *
     * @param name to test
     * @return true if pet name is already in use
     */
    public Pet getPet(String name) {
        return getPet(name, false);
    }

    /**
     * Return the Pet with the given name, or null if none found for this Owner.
     *
     * @param name to test
     * @return true if pet name is already in use
     */
    public Pet getPet(String name, boolean ignoreNew) {
        name = name.toLowerCase();
        for (Pet pet : getPetsInternal()) {
            if (!ignoreNew || !pet.isNew()) {
                String compName = pet.getName();
                compName = compName.toLowerCase();
                if (compName.equals(name)) {
                    return pet;
                }
            }
        }
        return null;
    }

    public Pet getPet(Integer petId) {
        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
    }

    @Override
    public String toString() {
        return new ToStringCreator(this)

            .append("id", this.getId())
            .append("new", this.isNew())
            .append("lastName", this.getLastName())
            .append("firstName", this.getFirstName())
            .append("address", this.address)
            .append("city", this.city)
            .append("telephone", this.telephone)
            .append("email", this.email)
            .toString();
    }
}

